            // Initialize all delay lines and outputs
            x_1_0 <= 0; x_1_1 <= 0; y_1_0 <= 0; y_1_1 <= 0;
            x_2_0 <= 0; x_2_1 <= 0; y_2_0 <= 0; y_2_1 <= 0;
